def choose_move(observation):
    width=observation['grid_width']
    height=observation['grid_height']
    grid=observation['grid']
    me_x,me_y=observation['self_position']
    opp_x,opp_y=observation['opponent_position']
    obstacles=observation['obstacles']
    resources=observation['resources']
    return_move=lambda dx,dy: [dx,dy]

    # Choose target: closest resource
    if resources:
        tx,ty=min(resources,key=lambda r: abs(r[0]-me_x)+abs(r[1]-me_y))
    else:
        tx,ty=me_x,me_y

    dx=dy=0
    if tx>me_x: dx=1
    elif tx<me_x: dx=-1
    if ty>me_y: dy=1
    elif ty<me_y: dy=-1

    next_x, next_y=me_x+dx, me_y+dy
    if 0<=next_x<width and 0<=next_y<height and (next_x,next_y) not in obstacles:
        return return_move(dx, dy)

    # Try to move vertically
    if dy!=0:
        alt_x=me_x
        alt_y=me_y+dy
        if 0<=alt_x<width and 0<=alt_y<height and (alt_x,alt_y) not in obstacles:
            return return_move(0,dy)

    # Try to move horizontally
    if dx!=0:
        alt_x=me_x+dx
        alt_y=me_y
        if 0<=alt_x<width and 0<=alt_y<height and (alt_x,alt_y) not in obstacles:
            return return_move(dx,0)

    # Stay if no move possible
    return return_move(0,0)
